//! Offline IP → country lookup and country flag images.
//!
//! Data is generated by `tools/gen_geo.py` from DB-IP Lite (CC BY 4.0, see README).

use iced::widget::image::Handle;
use std::collections::HashMap;
use std::net::{IpAddr, SocketAddr};
use std::sync::OnceLock;

static COUNTRY: &[u8] = include_bytes!("../assets/geo/country.bin");
static FLAGS: &[u8] = include_bytes!("../assets/geo/flags.bin");

const ENTRY: usize = 6;

fn u32_at(b: &[u8], i: usize) -> u32 {
    u32::from_le_bytes(b[i..i + 4].try_into().unwrap())
}

/// The two table sections of `country.bin`: (IPv4, IPv6), each a run of `ENTRY`-byte records.
fn sections() -> (&'static [u8], &'static [u8]) {
    let n4 = u32_at(COUNTRY, 0) as usize * ENTRY;
    let v4 = &COUNTRY[4..4 + n4];
    let rest = &COUNTRY[4 + n4..];
    let n6 = u32_at(rest, 0) as usize * ENTRY;
    (v4, &rest[4..4 + n6])
}

fn lookup(table: &[u8], key: u32) -> Option<[u8; 2]> {
    let n = table.len() / ENTRY;
    let start = |i: usize| u32::from_be_bytes(table[i * ENTRY..i * ENTRY + 4].try_into().unwrap());
    // Index of the first record that starts after `key`; the one before it covers `key`.
    let (mut lo, mut hi) = (0, n);
    while lo < hi {
        let mid = (lo + hi) / 2;
        if start(mid) <= key { lo = mid + 1 } else { hi = mid }
    }
    let i = lo.checked_sub(1)?;
    let cc = [table[i * ENTRY + 4], table[i * ENTRY + 5]];
    (cc != *b"ZZ").then_some(cc)
}

/// Country code (uppercase ASCII) for an address like `1.2.3.4:5`, `[::1]:5` or a bare IP.
pub fn country(addr: &str) -> Option<[u8; 2]> {
    let ip = addr.parse::<SocketAddr>().map(|s| s.ip()).or_else(|_| addr.parse::<IpAddr>()).ok()?;
    let (v4, v6) = sections();
    match ip {
        IpAddr::V4(a) => lookup(v4, a.into()),
        IpAddr::V6(a) => match a.to_ipv4_mapped() {
            Some(m) => lookup(v4, m.into()),
            None => lookup(v6, (u128::from(a) >> 96) as u32),
        },
    }
}

/// Flag image for a country code.
pub fn flag(cc: [u8; 2]) -> Option<&'static Handle> {
    static MAP: OnceLock<HashMap<[u8; 2], Handle>> = OnceLock::new();
    MAP.get_or_init(|| {
        let n = u16::from_le_bytes([FLAGS[0], FLAGS[1]]) as usize;
        (0..n)
            .map(|i| {
                let e = 2 + i * 10;
                let off = u32_at(FLAGS, e + 2) as usize;
                let len = u32_at(FLAGS, e + 6) as usize;
                ([FLAGS[e], FLAGS[e + 1]], Handle::from_bytes(&FLAGS[off..off + len]))
            })
            .collect()
    })
    .get(&cc)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cc(a: &str) -> Option<String> {
        country(a).map(|c| String::from_utf8_lossy(&c).into_owned())
    }

    #[test]
    fn resolves_known_addresses() {
        assert_eq!(cc("8.8.8.8:6881").as_deref(), Some("US"));
        assert_eq!(cc("77.88.8.8").as_deref(), Some("RU"));
        assert!(cc("[2a00:1450:4001:81b::200e]:51413").is_some());
        assert_eq!(cc("::ffff:8.8.8.8").as_deref(), Some("US"));
    }

    #[test]
    fn unknown_and_garbage_are_none() {
        assert_eq!(cc("10.0.0.1:1"), None);
        assert_eq!(cc("127.0.0.1"), None);
        assert_eq!(cc("not an address"), None);
    }

    #[test]
    fn common_countries_have_flags() {
        for a in ["8.8.8.8", "77.88.8.8", "1.1.1.1", "5.9.0.1", "202.108.22.5"] {
            assert!(flag(country(a).unwrap()).is_some(), "{a}");
        }
    }
}
